# Go Worker Pool with Graceful Shutdown

Here's a complete, production-ready worker pool implementation.

## Core Implementation

```go
package main

import (
	"context"
	"errors"
	"fmt"
	"log"
	"sync"
	"time"
)

// Job represents a unit of work to be processed.
type Job struct {
	ID    int
	Payload string
}

// WorkerPool manages a bounded pool of goroutines that process jobs
// from a channel with graceful shutdown support.
type WorkerPool struct {
	numWorkers int
	jobChan    chan Job
	wg         sync.WaitGroup
	mu         sync.Mutex
	stopCh     chan struct{}
	doneCh     chan struct{}
}

// NewWorkerPool creates a worker pool with the specified number of workers.
func NewWorkerPool(numWorkers int) *WorkerPool {
	if numWorkers <= 0 {
		numWorkers = 1
	}
	return &WorkerPool{
		numWorkers: numWorkers,
		jobChan:    make(chan Job),
		stopCh:     make(chan struct{}),
		doneCh:     make(chan struct{}),
	}
}

